// LINE-01 OPC UA Client READ 결과 → JSON 파싱
// msg.payload 는 OpcUa-Item 의 String 값 (line-DAS 의 EMIT 결과)
const raw = msg.payload;
if (raw === null || raw === undefined || raw === "") return null;
let obj;
try {
    obj = (typeof raw === 'string') ? JSON.parse(raw) : raw;
} catch (e) {
    node.warn(`LINE-01 parse error: ${e.message}`);
    return null;
}
if (!obj || !obj.line_id) {
    obj = obj || {};
    obj.line_id = "LINE-01";
}
msg.payload = obj;
msg.topic = obj.line_id;
return msg;

// payload 를 OPC UA Server 변수로 발행
//
// node-red-contrib-opcua 의 OpcUa-Server 는 2단계 프로토콜:
//   1) addVariable 명령으로 주소공간에 노드 등록
//      msg.topic   = 'ns=2;s=<name>;datatype=<DT>'
//      msg.payload = { opcuaCommand: 'addVariable' }
//   2) 이후 Variable 명령으로 값 갱신
//      msg.payload = { messageType:'Variable', namespace:2,
//                      variableName:<name>, variableValue:<val>, datatype:<DT> }
//
// addVariable 과 Variable 을 같은 tick 의 연속된 msg 로 보내면
// OpcUa-Server 가 주소공간 등록을 끝내기 전에 Variable 갱신이 들어와서
// "Variable not found" 에러가 다수 발생한다.
//
// 근본 해결책 (race 완전 제거):
//   1) 변수별 상태를 3단계로 관리: 'new' -> 'pending' -> 'ready'
//      - 처음 만난 변수는 addVariable 만 보내고 'pending' 으로 표시
//      - 다음 tick 부터 'pending' 인 변수는 Variable update SKIP 하고 'ready' 로 승격
//      - 'ready' 부터 실제 Variable update 전송
//   2) 즉 addVariable 보낸 tick (1초 간격) + 2 tick 뒤부터 update 시작
//      → OpcUa-Server 가 등록을 끝낼 약 1초 이상 확보
//   3) Variable update 는 contrib-opcua array payload 형식으로 한번에 묶어 전송
const EXPECTED_TYPES = {"CAST-01": {"power": "bool", "injection_pressure_sp": "float", "mold_temperature_sp": "float", "cooling_flow_sp": "float", "injection_pressure": "float", "mold_temperature": "float", "cooling_flow": "float", "progress": "float"}, "CNC-01": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "CNC-02": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "CNC-03": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "WASH-01": {"power": "bool", "cleaning_concentration_sp": "float", "cleaning_temperature_sp": "float", "cleaning_pressure_sp": "float", "cleaning_concentration": "float", "cleaning_temperature": "float", "cleaning_pressure": "float", "progress": "float"}, "ASSY-01": {"power": "bool", "tightening_torque_sp": "float", "tightening_angle_sp": "float", "press_force_sp": "float", "tightening_torque": "float", "tightening_angle": "float", "press_force": "float", "progress": "float"}, "ASSY-02": {"power": "bool", "tightening_torque_sp": "float", "tightening_angle_sp": "float", "press_force_sp": "float", "tightening_torque": "float", "tightening_angle": "float", "press_force": "float", "progress": "float"}, "TEST-01": {"power": "bool", "bore_dimension_sp": "float", "hole_dimension_sp": "float", "bore_dimension": "float", "hole_dimension": "float", "result_ok": "bool", "progress": "float"}, "TEST-02": {"power": "bool", "bore_dimension_sp": "float", "hole_dimension_sp": "float", "bore_dimension": "float", "hole_dimension": "float", "result_ok": "bool", "progress": "float"}};
const p = msg.payload;
if (!p) return null;
const lineId = p.line_id;
// state['name'] = 'pending' | 'ready'
const state = flow.get('opcua_state') || {};
const addMsgs = [];
const varList = [];

function coerce(value, dtype) {
  if (value === null || value === undefined) {
    if (dtype === 'Boolean') return false;
    if (dtype === 'Int32') return 0;
    if (dtype === 'Double' || dtype === 'Float') return 0.0;
    return '';
  }
  return value;
}

function publish(name, value, dtype) {
  const v = coerce(value, dtype);
  const s = state[name];
  if (!s) {
    // 첫 발견: addVariable 만 보냄
    addMsgs.push({
      topic: `ns=2;s=${name};datatype=${dtype}`,
      payload: { opcuaCommand: 'addVariable' },
    });
    state[name] = 'pending';
    return;
  }
  if (s === 'pending') {
    // 한 tick 더 기다림 -> ready 로 승격, 이번 tick 도 update skip
    state[name] = 'ready';
    return;
  }
  // ready: 실제 update
  varList.push({
    messageType: 'Variable',
    namespace: 2,
    variableName: name,
    variableValue: v,
    datatype: dtype,
  });
}

publish(`${lineId}.payload`,         JSON.stringify(p),     'String');
publish(`${lineId}.line_ts`,         p.ts,                   'String');
publish(`${lineId}.schema_version`,  p.schema_version,       'String');
for (const [eq, slot] of Object.entries(p.equipments || {})) {
  publish(`${lineId}.${eq}.status`,  slot.status,            'String');
  publish(`${lineId}.${eq}.ts`,      slot.ts,                'String');
  publish(`${lineId}.${eq}.quality`, slot.quality,           'String');
  const typeMap = (EXPECTED_TYPES[eq] || {});
  for (const [tag, val] of Object.entries(slot.data || {})) {
    let dtype;
    const declared = typeMap[tag];
    if (declared === 'bool') dtype = 'Boolean';
    else if (declared === 'int') dtype = 'Int32';
    else if (declared === 'float') dtype = 'Double';
    else {
      // 알려지지 않은 동적 tag (cycle_time, progress 등) — 무조건 Double 로 등록.
      if (typeof val === 'boolean') dtype = 'Boolean';
      else if (typeof val === 'number') dtype = 'Double';
      else dtype = 'String';
    }
    publish(`${lineId}.${eq}.data.${tag}`, val, dtype);
  }
}
flow.set('opcua_state', state);

// 단계 1: addVariable msg 들 즉시 전송 (array-of-messages 출력 형식)
if (addMsgs.length > 0) {
  node.send([addMsgs]);
}

// 단계 2: Variable update 는 array payload 로 한번에 전송 (state='ready' 인 것만)
//   addMsgs 가 있는 tick (새 변수 발견된 tick) 은 800ms 지연으로 안전 마진,
//   안정 상태에선 50ms 정도 지연으로 send 순서만 보장.
if (varList.length > 0) {
  const delay = (addMsgs.length > 0) ? 800 : 50;
  setTimeout(() => {
    node.send({ payload: varList });
  }, delay);
}

return null;

